import re,glob
reg=set(re.findall(r'^\s*"([a-z_]+)",', open('Agent/ToolErrors.hpp').read(), re.M))
found={}
for f in glob.glob('**/*.cpp',recursive=True)+glob.glob('**/*.hpp',recursive=True):
    if 'node_modules' in f: continue
    s=open(f).read()
    for pat in [r'(?<![A-Za-z_])fail\(\s*\w+,\s*"([a-z_]+)"', r'ToolError\{\s*"([a-z_]+)"', r'refuse\(\s*"([a-z_]+)"', r'ToolError\{\s*[^,{]*\?\s*"([a-z_]+)"\s*:\s*"([a-z_]+)"', r'issue\(\s*"([a-z_]+)"', r'SettingIssue\{\s*[^,]*,\s*"([a-z_]+)"', r'issues\.push_back\(\{\s*[^,{]*,\s*"([a-z_]+)"', r'issues\.push_back\(\{\s*"([a-z_]+)"']:
        for m in re.finditer(pat,s):
            for g in m.groups():
                found.setdefault(g,set()).add(f)
miss={k:v for k,v in found.items() if k not in reg}
print("unregistered:",miss)
print("registered but not seen:",sorted(reg-set(found)))
EOF

